from qdsl import Cat

c = Cat('quem_sou_eu', 'Quem sou eu?', '🕵️', 'Pistas escritas: descubra o personagem', '#7E57C2', order=40)
def Q(a, clues, d, src):
    c.Q('Quem sou eu?', a, clues, d, src=src)

Q('cleopatra', ['Governei o Egito por quase vinte anos, no século I a.C.', 'Falava vários idiomas e foi a primeira da minha dinastia a aprender egípcio.', 'Aliei-me a um general romano e depois a seu sucessor.', 'Terminei a vida em Alexandria, depois da derrota em Áccio.'], 2, ('pt', 'Cleópatra VII', ['Áccio']))
Q('cesar', ['Conquistei a Gália e escrevi sobre a guerra na terceira pessoa.', 'Cruzei um pequeno rio, com o exército, e desafiei o Senado.', 'Reformei o calendário romano.', 'Fui assassinado por senadores nos Idos de Março.'], 1, ('pt', 'Júlio César', ['calendário']))
Q('alexandre', ['Fui discípulo de um filósofo famoso, na adolescência.', 'Meu cavalo se chamava Bucéfalo.', 'Derrotei o rei persa Dario III.', 'Morri na Babilônia, antes de completar 33 anos.'], 1, ('pt', 'Alexandre, o Grande', ['Bucéfalo']))
Q('napoleao', ['Nasci numa ilha do Mediterrâneo, em 1769.', 'Tornei-me general durante a Revolução.', 'Coroei-me imperador em 1804.', 'Fui derrotado em Waterloo e morri em Santa Helena.'], 1, ('pt', 'Napoleão Bonaparte', ['Santa Helena']))
Q('leonardo', ['Nasci perto de Florença, em 1452.', 'Pintei um sorriso enigmático e uma ceia famosa.', 'Escrevia ao contrário, da direita para a esquerda, em cadernos cheios de invenções.', 'Morri na França, a convite do rei Francisco I.'], 1, ('pt', 'Leonardo da Vinci', ['Francisco I']))
Q('einstein', ['Nasci na Alemanha, em 1879, e trabalhei num escritório de patentes na Suíça.', 'Em 1905 publiquei quatro artigos que mudaram a Física.', 'Minha fórmula mais famosa liga energia, massa e a velocidade da luz.', 'Recebi o Nobel de Física em 1921.'], 1, ('pt', 'Albert Einstein', ['1921']))
Q('marie_curie', ['Nasci em Varsóvia, em 1867, e estudei em Paris.', 'Descobri dois elementos químicos, um deles batizado em homenagem à minha terra natal.', 'Fui a primeira pessoa a ganhar dois prêmios Nobel.', 'Meu trabalho com radioatividade custou-me a saúde.'], 2, ('pt', 'Marie Curie', ['Nobel']))
Q('gandhi', ['Fui advogado na África do Sul antes de voltar à Índia.', 'Liderei uma marcha de quase 400 km até o mar para fabricar sal.', 'Defendi a desobediência civil sem violência.', 'Fui assassinado em 1948, pouco depois da independência.'], 1, ('pt', 'Mahatma Gandhi', ['sal']))
Q('mandela', ['Fui advogado e líder de um movimento contra a segregação.', 'Passei 27 anos na prisão, grande parte em uma ilha.', 'Fui libertado em 1990.', 'Tornei-me presidente da África do Sul e recebi o Nobel da Paz.'], 1, ('pt', 'Nelson Mandela', ['Robben']))
Q('colombo', ['Nasci em Gênova, no século XV.', 'Convenci os reis católicos a financiar minha viagem.', 'Partia com três navios: Santa Maria, Pinta e Niña.', 'Julguei ter chegado às Índias, mas tinha chegado a outro continente.'], 1, ('pt', 'Cristóvão Colombo', ['Niña']))
Q('cabral', ['Nasci em Portugal, em 1467.', 'Comandei treze navios rumo à Índia, em 1500.', 'Desviei-me para o oeste e avistei um monte, que chamei Pascoal.', 'Deixei meu nome na história do Brasil.'], 1, ('pt', 'Pedro Álvares Cabral', ['Pascoal']))
Q('tiradentes', ['Fui alferes da cavalaria e também dentista, nascido em Minas Gerais.', 'Participei de uma conspiração contra a derrama.', 'Assumi a culpa sozinho no processo.', 'Fui executado no Rio de Janeiro, em 21 de abril de 1792.'], 1, ('pt', 'Tiradentes', ['1792']))
Q('dom_pedro_i', ['Nasci em Portugal e cheguei criança ao Brasil.', 'Em 1822, às margens de um riacho paulista, rompi com a metrópole.', 'Fui o primeiro imperador do Brasil.', 'Abdiquei em 1831 e voltei à Europa para defender o direito de minha filha ao trono português.'], 1, ('pt', 'Pedro I do Brasil', ['1831']))
Q('princesa_isabel', ['Nasci no Rio de Janeiro e fui herdeira do trono.', 'Governei o Império como regente em três ocasiões.', 'Em 13 de maio de 1888, assinei uma lei histórica.', 'Passei o resto da vida exilada na França, após a queda da monarquia.'], 1, ('pt', 'Isabel, Princesa Imperial do Brasil', ['Lei Áurea']))
Q('santos_dumont', ['Nasci em Minas Gerais, filho de um rico cafeicultor.', 'Mudei-me para Paris, onde construí balões dirigíveis.', 'Em 1906 fiz um voo público com um aparelho mais pesado que o ar.', 'Costumava usar um relógio de pulso feito para mim por Cartier.'], 1, ('pt', 'Alberto Santos-Dumont', ['Cartier']))
Q('machado', ['Nasci no Rio de Janeiro, no Morro do Livramento, em 1839.', 'Comecei como aprendiz de tipógrafo.', 'Fui o primeiro presidente da Academia Brasileira de Letras.', 'Escrevi sobre um narrador que duvidava de Capitu.'], 2, ('pt', 'Machado de Assis', ['Academia Brasileira de Letras']))
Q('getulio', ['Nasci em São Borja, no Rio Grande do Sul.', 'Cheguei ao poder em 1930 e governei por 15 anos seguidos.', 'Criei leis trabalhistas e uma grande companhia de petróleo.', 'Em 1954, deixei uma carta e um tiro no peito.'], 2, ('pt', 'Getúlio Vargas', ['1954']))
Q('jk', ['Nasci em Diamantina, Minas Gerais, e era médico.', 'Fui prefeito de Belo Horizonte e governador de Minas.', 'Prometi 50 anos de progresso em 5.', 'Inaugurei uma nova capital em 1960.'], 1, ('pt', 'Juscelino Kubitschek', ['Brasília']))
Q('lincoln', ['Nasci numa cabana, no Kentucky, e fui advogado.', 'Fui eleito presidente em 1860.', 'Liderei a União na guerra civil.', 'Fui assassinado num teatro, em 1865.'], 1, ('pt', 'Abraham Lincoln', ['teatro']))
Q('washington', ['Fui general de um exército de voluntários.', 'Atravessei o rio Delaware numa noite de Natal.', 'Presidi a Convenção que redigiu a Constituição.', 'Fui o primeiro presidente de meu país.'], 1, ('pt', 'George Washington', ['Delaware']))
Q('churchill', ['Fui correspondente de guerra, soldado e escritor.', 'Assumi como primeiro-ministro em 1940, depois da queda da França.', 'Prometi “sangue, trabalho, lágrimas e suor”.', 'Ganhei o Nobel de Literatura, em 1953.'], 2, ('pt', 'Winston Churchill', ['Nobel de Literatura']))
Q('shakespeare', ['Nasci em Stratford-upon-Avon, em 1564.', 'Escrevi cerca de 37 peças e 154 sonetos.', 'Uma de minhas peças fala de um príncipe dinamarquês e um fantasma.', 'Meu teatro, em Londres, chamava-se Globe.'], 1, ('pt', 'William Shakespeare', ['Globe']))
Q('mozart', ['Nasci em Salzburgo, em 1756.', 'Compus meu primeiro trabalho aos cinco anos.', 'Escrevi óperas como As Bodas de Fígaro e Don Giovanni.', 'Morri aos 35 anos, deixando um Réquiem inacabado.'], 1, ('pt', 'Wolfgang Amadeus Mozart', ['Réquiem']))
Q('beethoven', ['Nasci em Bonn, em 1770.', 'Comecei a perder a audição aos 28 anos.', 'Escrevi nove sinfonias.', 'Na última, pus um coro cantando a Ode à Alegria.'], 1, ('pt', 'Ludwig van Beethoven', ['Ode']))
Q('van_gogh', ['Nasci nos Países Baixos, em 1853.', 'Fui pastor e vendedor de arte antes de pintar.', 'Vendi apenas uma tela em vida, segundo a tradição.', 'Cortei parte da orelha e morri aos 37 anos.'], 2, ('pt', 'Vincent van Gogh', ['orelha']))
Q('picasso', ['Nasci em Málaga, em 1881.', 'Cofundei o Cubismo.', 'Pintei um mural em protesto contra o bombardeio de uma cidade basca.', 'Vivi até os 91 anos e deixei milhares de obras.'], 2, ('pt', 'Pablo Picasso', ['Guernica']))
Q('darwin', ['Nasci em Shrewsbury, em 1809.', 'Viajei por quase cinco anos num navio chamado Beagle.', 'Observei tentilhões e tartarugas em ilhas do Pacífico.', 'Publiquei, em 1859, a obra sobre a seleção natural.'], 1, ('pt', 'Charles Darwin', ['Beagle']))
Q('newton', ['Nasci em 1643, em Woolsthorpe.', 'Estudei em Cambridge e fui diretor da Casa da Moeda.', 'Descobri que a luz branca contém todas as cores.', 'Uma maçã me serviu de lenda para a gravitação.'], 1, ('pt', 'Isaac Newton', ['maçã']))
Q('galileu', ['Nasci em Pisa, em 1564.', 'Aperfeiçoei o telescópio e descobri luas de Júpiter.', 'Defendi que a Terra gira em torno do Sol.', 'Fui julgado pela Inquisição e passei os últimos anos em prisão domiciliar.'], 1, ('pt', 'Galileu Galilei', ['Júpiter']))
Q('marx', ['Nasci em Trier, em 1818, e estudei Direito e Filosofia.', 'Vivi grande parte da vida exilado em Londres.', 'Escrevi um manifesto com meu amigo Friedrich Engels.', 'Minha obra mais famosa analisa o capitalismo.'], 2, ('pt', 'Karl Marx', ['Engels']))
Q('lenin', ['Fui advogado e revolucionário russo.', 'Cheguei a São Petersburgo num trem lacrado, em 1917.', 'Liderei os bolcheviques.', 'Fundei a União Soviética, em 1922.'], 2, ('pt', 'Vladimir Lenin', ['1922']))
Q('luis_xiv', ['Subi ao trono com quatro anos.', 'Reinei por 72 anos, mais do que qualquer monarca europeu.', 'Escolhi o Sol como emblema.', 'Transformei um pavilhão de caça em palácio e mudei a corte para lá.'], 2, ('pt', 'Luís XIV de França', ['Sol']))
Q('elizabeth_i', ['Fui filha de Henrique VIII e Ana Bolena.', 'Reinei por 44 anos, sem me casar.', 'Minha esquadra venceu a Invencível Armada.', 'Minha época viu florescer o teatro de Shakespeare.'], 1, ('pt', 'Isabel I de Inglaterra', ['Armada']))
Q('augusto', ['Fui sobrinho-neto e herdeiro de um ditador romano.', 'Derrotei Marco Antônio e Cleópatra em Áccio.', 'Em 27 a.C., o Senado me deu um título honorífico.', 'Inaugurei duzentos anos de paz romana.'], 2, ('pt', 'Augusto', ['Áccio']))
Q('ramses_ii', ['Reinei por 66 anos, no Egito.', 'Enfrentei os hititas em Kadesh.', 'Mandei esculpir quatro estátuas gigantes na entrada de um templo na Núbia.', 'Tive mais de cem filhos, segundo os registros.'], 3, ('pt', 'Ramessés II', ['Kadesh']))
Q('tutancamon', ['Subi ao trono com nove anos.', 'Meu pai tentou impor um deus único.', 'Morri jovem, por volta dos 18 anos.', 'Minha tumba foi encontrada quase intacta em 1922.'], 1, ('pt', 'Tutancâmon', ['1922']))
Q('gengis', ['Nasci com o nome Temujin.', 'Unifiquei as tribos das estepes.', 'Criei o maior império contíguo da História.', 'Meus descendentes governaram da China à Rússia.'], 2, ('pt', 'Gengis Khan', ['Temujin']))
Q('joana_darc', ['Nasci num vilarejo da França, em 1412.', 'Disse ter ouvido vozes de santos.', 'Liderei tropas na libertação de Orléans.', 'Fui queimada em Rouen aos 19 anos.'], 1, ('pt', 'Joana d\'Arc', ['Orléans']))
Q('lutero', ['Fui monge agostiniano e professor de teologia.', 'Condenei a venda de indulgências em 95 teses.', 'Traduzi a Bíblia para o alemão.', 'Fui excomungado em 1521 e protegido por um príncipe.'], 2, ('pt', 'Martinho Lutero', ['indulgências']))
Q('bolivar', ['Nasci em Caracas, em 1783, numa família rica.', 'Jurei libertar meu continente da Espanha.', 'Liderei campanhas pela Venezuela, Colômbia, Equador, Peru e Bolívia.', 'Sonhava com uma América do Sul unida; um país leva meu nome.'], 2, ('pt', 'Simón Bolívar', ['Bolívia']))
Q('frida', ['Nasci no México, em 1907, e sofri um grave acidente aos 18 anos.', 'Pintei muitos autorretratos.', 'Casei duas vezes com o mesmo muralista.', 'Minha casa azul, na Cidade do México, é hoje museu.'], 2, ('pt', 'Frida Kahlo', ['Casa Azul']))
Q('anne_frank', ['Nasci em Frankfurt, em 1929.', 'Mudei-me para Amsterdã com minha família.', 'Escondi-me por mais de dois anos num anexo secreto.', 'Meu diário foi publicado pelo meu pai depois da guerra.'], 1, ('pt', 'Anne Frank', ['anexo']))
Q('mlk', ['Nasci em Atlanta, em 1929, e fui pastor batista.', 'Liderei o boicote aos ônibus em Montgomery.', 'Em 1963, discursei em Washington sobre um sonho.', 'Ganhei o Nobel da Paz e fui assassinado em Memphis, em 1968.'], 1, ('pt', 'Martin Luther King Jr.', ['Memphis']))
Q('gagarin', ['Fui piloto e filho de camponeses.', 'Em 12 de abril de 1961, completei uma volta à Terra.', 'Minha nave se chamava Vostok 1.', 'Morri num treinamento aéreo, aos 34 anos.'], 1, ('pt', 'Yuri Gagarin', ['Vostok']))
Q('pasteur', ['Nasci em 1822 no Jura, na França.', 'Descobri que micróbios causam doenças.', 'Criei um processo de aquecer o leite para destruir bactérias.', 'Desenvolvi vacinas contra a raiva e o antraz.'], 2, ('pt', 'Louis Pasteur', ['antraz']))
Q('mansa_musa', ['Governei o Mali no século XIV.', 'Fiz uma peregrinação a Meca com milhares de pessoas e toneladas de ouro.', 'Distribuí tanto ouro no Cairo que o preço do metal caiu.', 'Fui talvez o homem mais rico de todos os tempos.'], 3, ('pt', 'Mansa Mussa', ['ouro']))
Q('zumbi', ['Nasci livre, em Alagoas, mas fui entregue a um padre ainda criança.', 'Fugi e voltei à serra da Barriga.', 'Liderei um quilombo com milhares de pessoas.', 'Fui morto em 20 de novembro de 1695.'], 2, ('pt', 'Zumbi dos Palmares', ['serra da Barriga']))
Q('tchaikovsky', ['Nasci na Rússia, em 1840.', 'Estudei Direito antes de me dedicar à música.', 'Compus balés como O Quebra-Nozes.', 'Escrevi também a Abertura 1812, com canhões.'], 3, ('pt', 'Piotr Ilitch Tchaikovski', ['Quebra-Nozes']))
Q('pedro_grande', ['Tinha mais de dois metros de altura.', 'Viajei incógnito pela Europa para aprender ofícios.', 'Cortei as barbas dos nobres e fundei uma nova capital no Báltico.', 'Fui o primeiro a me proclamar imperador de todas as Rússias.'], 3, ('pt', 'Pedro I da Rússia', ['barba']))
Q('henrique_viii', ['Subi ao trono em 1509.', 'Casei seis vezes.', 'Rompi com o papa e me fiz chefe da Igreja da Inglaterra.', 'Minhas filhas Maria e Elizabeth reinaram depois de mim.'], 1, ('pt', 'Henrique VIII de Inglaterra', ['seis']))
Q('aristoteles', ['Nasci em Estagira, em 384 a.C.', 'Estudei na Academia por vinte anos.', 'Fui preceptor de um jovem príncipe macedônio.', 'Fundei uma escola chamada Liceu.'], 2, ('pt', 'Aristóteles', ['Liceu']))
Q('socrates', ['Nunca escrevi nada: meus diálogos foram registrados por discípulos.', 'Dizia “só sei que nada sei”.', 'Fui acusado de corromper a juventude e desrespeitar os deuses.', 'Tomei cicuta em 399 a.C.'], 1, ('pt', 'Sócrates', ['cicuta']))
Q('pericles', ['Fui general e orador ateniense.', 'Governei Atenas por cerca de trinta anos.', 'Patrocinei a reconstrução da Acrópole.', 'Morri durante uma peste, no início da guerra contra Esparta.'], 3, ('pt', 'Péricles', ['peste']))
